def flood_outer(grid, background):
    """Find all background cells connected to grid boundary."""
    h, w = len(grid), len(grid[0])
    reachable = set()
    queue = []

    # Add all boundary background cells
    for r in range(h):
        if grid[r][0] == background:
            queue.append((r, 0))
            reachable.add((r, 0))
        if grid[r][w-1] == background:
            queue.append((r, w-1))
            reachable.add((r, w-1))
    for c in range(w):
        if grid[0][c] == background:
            queue.append((0, c))
            reachable.add((0, c))
        if grid[h-1][c] == background:
            queue.append((h-1, c))
            reachable.add((h-1, c))

    # BFS
    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in reachable:
                if grid[nr][nc] == background:
                    reachable.add((nr, nc))
                    queue.append((nr, nc))

    return reachable

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = 1
    border = 3

    reachable = flood_outer(grid, background)

    result = [row[:] for row in grid]

